package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B9ResultPlanTest extends TestCase {
    static ObjectNode plan(){return (ObjectNode)parse("{\"goal\":\"copy result\",\"steps\":[{\"stepId\":\"D\",\"tool\":\"build_dataset\",\"dependsOn\":[],\"verificationRules\":[{\"type\":\"tool_success\"}],\"inputBindings\":{\"sheetId\":\"s\",\"range\":\"A1:B3\",\"headerRow\":true,\"includeHidden\":true,\"includeFiltered\":true,\"formulaPolicy\":\"reject\"}},{\"stepId\":\"W\",\"tool\":\"write_result\",\"dependsOn\":[\"D\"],\"verificationRules\":[{\"type\":\"tool_success\"}],\"inputBindings\":{\"dataset\":{\"$step\":\"D\"},\"sheetId\":\"out\",\"range\":\"A1:B3\",\"overwrite\":\"empty-only\"}},{\"stepId\":\"V\",\"tool\":\"verify_result\",\"dependsOn\":[\"W\"],\"verificationRules\":[{\"type\":\"tool_success\"}],\"inputBindings\":{\"write\":{\"$step\":\"W\"},\"sheetId\":\"out\",\"range\":\"A1:B3\",\"kind\":\"matches_write\"}}],\"acceptanceCriteria\":[{\"type\":\"step_succeeded\",\"stepId\":\"D\"},{\"type\":\"step_succeeded\",\"stepId\":\"W\"},{\"type\":\"step_succeeded\",\"stepId\":\"V\"}]}");}
    private void reject(Runnable r){try{r.run();fail("unsafe plan accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testAdapterIsAdmissionOnlyAndDisabledByDefault(){ObjectNode original=plan(),copy=(ObjectNode)ResultPlan.admissionCopy(original,true);assertEquals("write_result",original.path("steps").get(1).path("tool").asText());assertEquals("apply_actions",copy.path("steps").get(1).path("tool").asText());AgentPlan.validate(copy);reject(()->ResultPlan.admissionCopy(original,false));}
    public void testPersistedServerStepResultsDoNotBecomeModelInputs(){ObjectNode original=plan();((ObjectNode)original.path("steps").get(0)).set("resultRefs",obj().put("resultRef","server-issued").put("sourceRevision","server-version"));AgentPlan.validate(ResultPlan.admissionCopy(original,true));}
    public void testForgedRefSourceTargetAndVerificationReject(){ObjectNode p=plan();((ObjectNode)p.path("steps").get(1).path("inputBindings")).put("sheetId","s");reject(()->ResultPlan.admissionCopy(p,true));ObjectNode literal=plan();((ObjectNode)literal.path("steps").get(1).path("inputBindings")).set("dataset",obj().put("resultRef","forged"));final ObjectNode forged=literal;reject(()->ResultPlan.admissionCopy(forged,true));ObjectNode wrong=plan();((ObjectNode)wrong.path("steps").get(2).path("inputBindings")).put("range","A1:B2");reject(()->ResultPlan.admissionCopy(wrong,true));ObjectNode highlight=plan();((ObjectNode)highlight.path("steps").get(1).path("inputBindings")).set("highlight",obj());reject(()->ResultPlan.admissionCopy(highlight,true));}
}
